-- Core schema (both editions): users, sessions, magic links, email log, and the demo "notes" resource.
-- Timestamps are Unix seconds (INTEGER). IDs are opaque strings generated by the app.
-- Apply locally with `npm run db:migrate:local`, in production with `npm run db:migrate:remote`.

CREATE TABLE users (
  id            TEXT PRIMARY KEY,
  email         TEXT NOT NULL UNIQUE,
  role          TEXT NOT NULL DEFAULT 'user',   -- 'user' | 'admin' (admins come from ADMIN_EMAILS)
  plan          TEXT NOT NULL DEFAULT 'free',   -- 'free' | 'pro' | 'lifetime'; written only by billing webhooks
  created_at    INTEGER NOT NULL,
  last_login_at INTEGER
);

-- A session row stores the SHA-256 of the cookie token, never the token itself.
CREATE TABLE sessions (
  id           TEXT PRIMARY KEY,
  user_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at   INTEGER NOT NULL,
  expires_at   INTEGER NOT NULL,
  last_seen_at INTEGER NOT NULL,
  user_agent   TEXT
);
CREATE INDEX sessions_user_id ON sessions(user_id);
CREATE INDEX sessions_expires_at ON sessions(expires_at);

-- Magic links are single use and short lived. The row id is the SHA-256 of the token in the URL.
CREATE TABLE magic_links (
  id         TEXT PRIMARY KEY,
  email      TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL,
  used_at    INTEGER
);
CREATE INDEX magic_links_email_created ON magic_links(email, created_at);

-- Every outgoing email is recorded here. In development (no RESEND_API_KEY) this table IS the outbox.
CREATE TABLE email_log (
  id          TEXT PRIMARY KEY,
  to_email    TEXT NOT NULL,
  subject     TEXT NOT NULL,
  text_body   TEXT NOT NULL,
  provider    TEXT NOT NULL,              -- 'resend' | 'outbox'
  provider_id TEXT,
  status      TEXT NOT NULL,              -- 'sent' | 'queued' | 'failed'
  error       TEXT,
  created_at  INTEGER NOT NULL
);
CREATE INDEX email_log_created ON email_log(created_at);

-- Demo resource. Replace or extend it with your own domain objects (see docs/add-a-feature.md).
CREATE TABLE notes (
  id         TEXT PRIMARY KEY,
  user_id    TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  title      TEXT NOT NULL,
  body       TEXT NOT NULL DEFAULT '',
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE INDEX notes_user_created ON notes(user_id, created_at);
